
import CardMedia from '@mui/material/CardMedia';

import { useNavigate, useParams} from 'react-router-dom';
import CloseIcon from '@mui/icons-material/Close';
import IconButton from '@mui/material/IconButton';
import Stack from '@mui/material/Stack';

console.log("######### Book.js ######### ");

export default function Book() {
    const {book} = useParams();
    console.log("book "+book+": "+window.location.href)
    const navigate = useNavigate(); //const navigate = () => { }

    return (
    <Stack style={{paddingTop:'0px'}}>
            <Stack style={{position:'absolute', top:65, right:15}}>
                <IconButton color="primary" aria-label="minimize" onClick={()=>navigate("/books")} >
                    <CloseIcon />
                </IconButton>
            </Stack>
           <CardMedia

             style={{border:0}}
             component = "iframe"
             src={"https://taotool.github.io/"+book}
             height="1000"
             width="1000">
           </CardMedia>
           </Stack>
    );
  }