import * as d3 from "d3";
import "./Grid.css";
import svgPanZoom from "svg-pan-zoom";
import { panZoom } from "./SvgPanZoomHammer.js";
export const drawGrid = (inputGridData) => {
  const numRows = inputGridData.length;
  const numCols = inputGridData[0].length;
  const CELL_SIZE = 50;
  const margin = { top: 10, right: 10, bottom: 10, left: 10 };
  const width = numCols * CELL_SIZE + 50 + margin.left + margin.right;
  const height = numRows * CELL_SIZE + 50 + margin.top + margin.bottom;

  // Grid data generator
  const generateGridData = () => {
    const data = [];
    let xpos = CELL_SIZE / 2;
    let ypos = CELL_SIZE / 2;

    for (let row = 0; row < numRows; row++) {
      const rowData = [];
      for (let col = 0; col < numCols; col++) {
        const cellData = inputGridData[row][col];
        rowData.push({
          x: xpos,
          y: ypos,
          width: CELL_SIZE,
          height: CELL_SIZE,
          click: 0, // Counter for click states
          value: cellData,
          lt: row + "," + col, // Default cell value
          rt:"",
          lb:"",
          rb:"",
        });
        xpos += CELL_SIZE;
      }
      data.push(rowData);
      xpos = CELL_SIZE / 2; // Reset X position
      ypos += CELL_SIZE; // Increment Y position
    }
    return data;
  };

  const fadeOut = () => {
    document.querySelector("#grid").classList.add("fade-out");
  };

  const fadeIn = () => {
    document.querySelector("#grid").classList.remove("fade-out");
  };
  const gridData = generateGridData();

  // Clear existing grid
  d3.select("#grid").selectAll("*").remove();

  // I like to log the data to the console for quick debugging
  //console.log(gridData);
  //d3.select("#grid").selectAll('*').remove();
  const svg = d3
    .select("#grid")
    .append("svg")
    //.attr("id", "svg-grid") // Add an ID for svg-pan-zoom to target
    .attr("width", "100%")
    .attr("height", "100%");

  //    .attr("width", width) // Ensure non-zero width
  //    .attr("height", height); // Ensure non-zero height

  //    svg.attr("viewBox", `0 0 ${width} ${height}`)
  //       .attr("preserveAspectRatio", "xMidYMid meet");

  // Define scales
  const xScale = d3
    .scaleLinear()
    .domain([0, numCols + 1])
    .range([margin.left, width - margin.right]);

  const yScale = d3
    .scaleLinear()
    .domain([0, numRows + 1])
    .range([margin.top, height - margin.bottom]);

  // Append axes 1
  svg
    .append("g")
    .attr("transform", `translate(0,${margin.top})`)
    //.call(d3.axisBottom(xScale).ticks(11))
    //.call(d3.axisTop(xScale).tickFormat(d => `${d==0||d==numCols+1?'':d-1}`))
    .call(
      d3
        .axisTop(xScale)
        .ticks(numCols + 1)
        .tickFormat((d) => `${d == 0 || d == numCols + 1 ? "" : d - 1}`)
    )
    .attr("class", "axis");

  // Append axes 2
  svg
    .append("g")
    .attr("transform", `translate(0,${height - margin.bottom})`)
    //.call(d3.axisBottom(xScale).ticks(11))
    //.call(d3.axisTop(xScale).tickFormat(d => `${d==0||d==numCols+1?'':d-1}`))
    .call(
      d3
        .axisBottom(xScale)
        .ticks(numCols + 1)
        .tickFormat((d) => `${d == 0 || d == numCols + 1 ? "" : d - 1}`)
    )
    .attr("class", "axis");
  // Add a dynamic letter 'i' under the x-axis
  svg
    .append("text")
    .attr("id", "dynamic-label-j")
    .attr("y", -30) // Slightly below the x-axis
    .attr("text-anchor", "middle")
    .attr("font-size", "14px")
//    .text("jx")
    ;
  // Add a dynamic letter 'i' under the x-axis
  svg
    .append("text")
    .attr("id", "dynamic-label-c")
    .attr("y", height + 30) // Slightly below the x-axis
    .attr("text-anchor", "middle")
    .attr("font-size", "14px")
//    .text("col")
    ;
  // Append y-axis
  svg
    .append("g")
    .attr("transform", `translate(${margin.left},0)`)
    .call(
      d3
        .axisLeft(yScale)
        .ticks(numRows + 1)
        .tickFormat((d) => `${d == 0 || d == numRows + 1 ? "" : d - 1}`)
    )
    .attr("class", "axis");

  // Append y-axis 2
  svg
    .append("g")
    .attr("transform", `translate(${width-margin.right},0)`)
    .call(
      d3
        .axisRight(yScale)
        .ticks(numRows + 1)
        .tickFormat((d) => `${d == 0 || d == numRows + 1 ? "" : d - 1}`)
    )
    .attr("class", "axis");
  svg
    .append("text")
    .attr("id", "dynamic-label-i")
    .attr("x", -40) // Slightly below the x-axis
    .attr("text-anchor", "middle")
    .attr("font-size", "14px")
//    .text("iy")
    ;

   svg
     .append("text")
     .attr("id", "dynamic-label-r")
     .attr("x", width+30) // Slightly below the x-axis
     .attr("text-anchor", "middle")
     .attr("font-size", "14px")
//     .text("row")
     ;
  // Bind rows
  var row = svg
    .selectAll(".row")
    .data(gridData)
    .enter()
    .append("g")
    .attr("class", "row");

  // Bind cells (rectangles) and add text inside each
  const cells = row
    .selectAll(".square")
    .data((d) => d)
    .enter()
    .append("g")
    .attr("class", "cell");

  cells
    .append("rect")
    .attr("class", "square")
    .attr("x", (d) => d.x + margin.left)
    .attr("y", (d) => d.y + margin.top)
    .attr("width", (d) => d.width)
    .attr("height", (d) => d.height)
    //.style("fill", (d) => (d.value === "1" ? "#2C93E8" : ""))
    .on("click", function (d) {
//      this.__data__.click++;
//      if (this.__data__.click % 4 === 0) d3.select(this).style("fill", "#fff");
//      if (this.__data__.click % 4 === 1)
//        d3.select(this).style("fill", "#2C93E8");
//      if (this.__data__.click % 4 === 2)
//        d3.select(this).style("fill", "#F56C4E");
//      if (this.__data__.click % 4 === 3)
//        d3.select(this).style("fill", "#838690");
    });

  // Add text elements inside each cell
  cells
    .append("text")
    .attr("class", "cell-text")
    .attr("x", (d) => d.x + margin.left + CELL_SIZE / 2)
    .attr("y", (d) => d.y + margin.top + CELL_SIZE / 2)
    .attr("text-anchor", "middle")
    .attr("dominant-baseline", "middle")
    .attr("font-size", "14px")
    .text((d) => d.value);
  cells
    .append("text")
    .attr("class", "cell-lt")
    .attr("x", (d) => d.x + margin.left + 10) //.attr("x", d => d.x + margin.left + CELL_SIZE / 2)
    .attr("y", (d) => d.y + margin.top + 10) //.attr("y", d => d.y + margin.top + CELL_SIZE / 2)
    .attr("text-anchor", "middle")
    .attr("dominant-baseline", "middle")
    .attr("font-size", "5px")
    .text((d) => d.lt);

  cells
    .append("text")
    .attr("class", "cell-lb")
    .attr("x", (d) => d.x + margin.left + 10) //.attr("x", d => d.x + margin.left + CELL_SIZE / 2)
    .attr("y", (d) => d.y + margin.top + CELL_SIZE-10) //.attr("y", d => d.y + margin.top + CELL_SIZE / 2)
    .attr("text-anchor", "middle")
    .attr("dominant-baseline", "middle")
    .attr("font-size", "5px")
    .text((d) => d.lb);
  cells
    .append("text")
    .attr("class", "cell-rb")
    .attr("x", (d) => d.x + margin.left + CELL_SIZE-10) //.attr("x", d => d.x + margin.left + CELL_SIZE / 2)
    .attr("y", (d) => d.y + margin.top + CELL_SIZE-10) //.attr("y", d => d.y + margin.top + CELL_SIZE / 2)
    .attr("text-anchor", "middle")
    .attr("dominant-baseline", "middle")
    .attr("font-size", "5px")
    .text((d) => d.rb);
  cells
    .append("text")
    .attr("class", "cell-rt")
    .attr("x", (d) => d.x + margin.left + CELL_SIZE-10) //.attr("x", d => d.x + margin.left + CELL_SIZE / 2)
    .attr("y", (d) => d.y + margin.top + 10) //.attr("y", d => d.y + margin.top + CELL_SIZE / 2)
    .attr("text-anchor", "middle")
    .attr("dominant-baseline", "middle")
    .attr("font-size", "5px")
    .text((d) => d.rt);

  fadeOut();
  const updateCellLT = (rowIdx, colIdx, newValue) => {
    updateCellV(rowIdx, colIdx, newValue, "lt");
  }
  const updateCellRT = (rowIdx, colIdx, newValue) => {
    updateCellV(rowIdx, colIdx, newValue, "rt");
  }
  const updateCellLB = (rowIdx, colIdx, newValue) => {
    updateCellV(rowIdx, colIdx, newValue, "lb");
  }
  const updateCellRB = (rowIdx, colIdx, newValue) => {
    updateCellV(rowIdx, colIdx, newValue, "rb");
  }
  const updateCellValue = (rowIdx, colIdx, newValue) => {
    updateCellV(rowIdx, colIdx, newValue, "value");
  }
  // Function to update a specific cell value
  const updateCellValue2 = (rowIdx, colIdx, newValue) => {
    console.log(gridData);
    if (rowIdx >= 0 && rowIdx < numRows && colIdx >= 0 && colIdx < numCols) {
      gridData[rowIdx][colIdx].value = newValue;

      d3.selectAll(".cell-text")
        .data(gridData.flat())
        .text((d) => d.value);
    } else {
      console.error("Invalid row or column index");
    }
  };

  const updateCellV = (rowIdx, colIdx, newValue, id) => {
    console.log(gridData);
    if (rowIdx >= 0 && rowIdx < numRows && colIdx >= 0 && colIdx < numCols) {
      gridData[rowIdx][colIdx][id] = newValue;

      d3.selectAll(".cell-text")
        .data(gridData.flat())
        .text((d) => d.value);
      d3.selectAll(".cell-lt")
        .data(gridData.flat())
        .text((d) => d.lt);
      d3.selectAll(".cell-rt")
        .data(gridData.flat())
        .text((d) => d.rt);
      d3.selectAll(".cell-lb")
        .data(gridData.flat())
        .text((d) => d.lb);
      d3.selectAll(".cell-rb")
        .data(gridData.flat())
        .text((d) => d.rb);
    } else {
      console.error("Invalid row or column index");
    }
  };
  const updateCellClass = (rowIdx, colIdx, newClass) => {
    newClass = newClass ? "square " + newClass : "square";
    if (rowIdx >= 0 && rowIdx < numRows && colIdx >= 0 && colIdx < numCols) {
      // Find the corresponding cell group and update its class
      d3.selectAll(".square")
        .filter((d, i, nodes) => {
          // Identify the correct cell using data index
          const cellData = d3.select(nodes[i]).datum();
          return (
            gridData[rowIdx][colIdx].x === cellData.x &&
            gridData[rowIdx][colIdx].y === cellData.y
          );
        })
        .attr("class", newClass);
    } else {
      console.error("Invalid row or column index");
    }
  };

  const updateDynamicLabel = (id, idx, newLabelText) => {
    const tickPosition = (idx + 1) * CELL_SIZE + margin.left;
    const axis = id == "i"||id=="r" ? "y" : "x";
    //            if (tickPosition !== undefined) {
    d3.select("#dynamic-label-" + id)
      .transition()
      .duration(750)
      .text(newLabelText)
      .attr(axis, tickPosition); // Centered on the tick
    //            }
  };
  // Return the chart with updating functions.
  return Object.assign(svg.node(), {
    updateDynamicLabel,
    updateCellValue,
    updateCellLT,
    updateCellRT,
    updateCellLB,
    updateCellRB,
    updateCellClass,
    fadeOut,
    fadeIn,
  });
};
