import { memo } from 'react'
import { useNavigate } from 'react-router-dom';

import * as React from 'react';
import Card from '@mui/material/Card';
import CardActions from '@mui/material/CardActions';
import CardContent from '@mui/material/CardContent';
import CardMedia from '@mui/material/CardMedia';
import Button from '@mui/material/Button';
import Typography from '@mui/material/Typography';
import Grid from '@mui/material/Grid2';
import Box from '@mui/material/Box';
console.log("######### Books.js ######### ");

function Books() {
    console.log("books "+window.location.href)
    const navigate = useNavigate(); //     const navigate = useNavigate();


    const goToDashboard = (url) => {
        navigate(url); // Navigate to /dashboard
    };
   return (
    <Box sx={{ flexGrow: 1, p: 0 }} style={{margin:'0px'}}>
      <Grid
        container
        spacing={1}
        sx={{
          '--Grid-borderWidth': '1px',
          borderTop: 'var(--Grid-borderWidth) solid',
          borderLeft: 'var(--Grid-borderWidth) solid',
          borderColor: 'divider',
          '& > div': {
            borderRight: 'var(--Grid-borderWidth) solid',
            borderBottom: 'var(--Grid-borderWidth) solid',
            borderColor: 'divider',
          },
        }}
      >

          <Grid
            key='1'
            minHeight={160}
            size={{
              xs: 12,
              sm: 6,
              md: 4,
              lg: 3,
            }}
          >
                <Card sx={{ minHeight: 360 , cursor: 'pointer'}}
                onClick={()=>goToDashboard('/books/leetcode')}>
                    <CardMedia
                      component="img"
                      alt="green iguana"
                      height="140"
                      image="https://mui.com/static/images/cards/contemplative-reptile.jpg"
                    />
                    <CardContent>
                      <Typography gutterBottom variant="h5" component="div">
                        LeetCode Notes
                      </Typography>
                      <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                        Without accumulating small steps, one cannot reach a thousand miles;

                        without gathering small streams, one cannot form a river or sea.

                        —— Xunzi (c. 310 – c. 235 BC, alt. c. 314 – c. 217 BC)
                      </Typography>
                    </CardContent>
                    <CardActions>

                      <Button size="small" onClick={()=>goToDashboard('/books/leetcode')}>
                       Open Book
                      </Button>
                      <Button size="small">Share</Button>
                    </CardActions>
                  </Card>
          </Grid>


          <Grid
              key='2'
              minHeight={160}
              size={{
                xs: 12,
                sm: 6,
                md: 4,
                lg: 3,
              }}
            >
                  <Card sx={{ minHeight: 360,cursor: 'pointer' }}
                  onClick={()=>goToDashboard('/books/designpattern')}>
                      <CardMedia
                        component="img"
                        alt="green iguana"
                        height="140"
                        image="https://mui.com/static/images/cards/contemplative-reptile.jpg"
                      />
                      <CardContent>
                        <Typography gutterBottom variant="h5" component="div">
                          Design Patterns
                        </Typography>
                        <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                          Is it not a pleasure, having learned something,

                          to practice it at regular intervals?

                          —— Confucius’ Analects
                        </Typography>
                      </CardContent>
                      <CardActions>
                        <Button size="small" onClick={()=>goToDashboard('/books/designpattern')}>
                         Open Book
                        </Button>
                        <Button size="small">Share</Button>

                      </CardActions>
                    </Card>
            </Grid>


      </Grid>
    </Box>
     );
}

export default memo(Books)