import * as d3 from "d3";
import "./Grid.css";
import clone from "clone";

export const drawQueue = (inputQueueData) => {
  const numRows = 1;
  const numCols = inputQueueData.length; // Number of stack elements
  const CELL_SIZE = 50;
  const margin = { top: 10, right: 10, bottom: 10, left: 10 };
//  const width = CELL_SIZE + margin.left + margin.right; // Single column
//  const height = numRows * CELL_SIZE + margin.top + margin.bottom;
  const width = numCols * CELL_SIZE + margin.left + margin.right; // Horizontal layout
  const height = CELL_SIZE + margin.top + margin.bottom;


  const generateQueueData = () => {
    const data = [];
    let xpos = CELL_SIZE / 2; // Start at the first cell's center

    for (let i = 0; i < numCols; i++) {
      const cellData = inputQueueData[i];
      data.push({
        x: xpos,
        y: height / 2, // Vertically centered
        width: CELL_SIZE,
        height: CELL_SIZE,
        click: 0,
        value: cellData,
        pos: i, // Position index
      });
      xpos += CELL_SIZE; // Increment X position
    }
    return data;
  };


  const fadeOut = () => {
    document.querySelector("#queue").classList.add("fade-out");
  };

  const fadeIn = () => {
    document.querySelector("#queue").classList.remove("fade-out");
  };

  let queueData = generateQueueData();
  const drawSvg = () => {
    let svg = d3.select("#queue svg");
    let svg_with_zoom = d3.select("#queue svg g");
    if (svg.empty()) {
      svg = d3
        .select("#queue")
        .append("svg")
        .attr("fill", "yellow")
        .attr("width", "100%")
        .attr("height", "100%");

    } else if (!svg_with_zoom.empty()) {
      svg = svg_with_zoom;
    }

    // Bind data to group elements
    const cells = svg.selectAll(".cell").data(queueData, (d) => d.pos); // Use `pos` as a unique key

    // Enter phase: Add new elements for new data
    const cellsEnter = cells.enter().append("g").attr("class", "cell");

    cellsEnter
      .append("rect")
      .attr("class", "square")
      .attr("width", CELL_SIZE)
      .attr("height", CELL_SIZE)
      .attr("x", (d) => d.x - CELL_SIZE / 2)
      .attr("y", (d) => d.y - CELL_SIZE / 2)
      //.style("stroke", "#000")
      .style("stroke-width", (d, i) => (i === 0 ? "1px" : "1px"))
      .on("click", function () {
//        const cellData = d3.select(this).datum();
//        cellData.click++;
//        d3.select(this).style(
//          "fill",
//          cellData.click % 2 === 0 ? "#2C93E8" : "#F56C4E"
//        );
      });

    cellsEnter
      .append("text")
      .attr("class", "cell-text")
      .attr("text-anchor", "middle")
      .attr("dominant-baseline", "middle")
      .attr("font-size", "14px")
      .text((d) => d.value);

    // Update phase: Update existing elements
    const mergedCells = cells.merge(cellsEnter);

    mergedCells
      .select("rect")
      .transition()
      .duration(300) // Animation for smooth update
      .attr("x", (d) => d.x - CELL_SIZE / 2)
      .attr("y", (d) => d.y - CELL_SIZE / 2);

    mergedCells
      .select("text")
      .transition()
      .duration(300)
      .attr("x", (d) => d.x)
      .attr("y", (d) => d.y)
      .text((d) => d.value);

    // Exit phase: Remove elements no longer in the data
    cells.exit().remove();
    return svg;
  };

  const offer = (value) => {
    // Add the new value at the tail (right side) of the queue
    const w = queueData.length*CELL_SIZE;

    queueData.push({
      x: 0 ,
      y: 0, // Start above the visible area for animation
      width: CELL_SIZE,
      height: CELL_SIZE,
      click: 0,
      value,
      pos: Date.now(), // Use a unique identifier (e.g., timestamp)
    });

    // Recalculate positions for all elements
    const centerXOffset =  (width - w) / 2;
    queueData.forEach((cell, index) => {
      cell.x = centerXOffset+index * CELL_SIZE;
      cell.y = height / 2; // Center horizontally
    });

    // Update the queue visually without fully redrawing
    drawSvg();
  };

  const poll = () => {
    if (queueData.length === 0) {
      console.info("Cannot pop from an empty queue");
      return null;
    }
    const w = queueData.length*CELL_SIZE;

    // Remove the last element
    const removedElement = queueData.shift();

    // Recalculate positions
    const centerXOffset =  (width - w) / 2;
    queueData.forEach((cell, index) => {
      cell.y = height / 2;
      cell.x = centerXOffset + (index + 0.5) * CELL_SIZE;
    });

    // Update the stack visually
    drawSvg();

    return removedElement.value;
  };

  const updateCellValue = (index, newValue) => {
    if (index >= 0 && index < queueData.length) {
      queueData[index].value = newValue;

      d3.selectAll(".cell-text")
        .data(queueData)
        .text((d) => d.value);
    } else {
      console.error("Invalid index");
    }
  };

  const updateCellClass = (idx, newClass) => {
    newClass = newClass ? "square " + newClass : "square";
    if (idx >= 0 && idx < queueData.length) {
      d3.selectAll(".square")
        .filter((d, i, nodes) => {
          const cellData = d3.select(nodes[i]).datum();
          return (
            queueData[idx].x === cellData.x && queueData[idx].y === cellData.y
          );
        })
        .attr("class", newClass);
    } else {
      console.error("Invalid index");
    }
  };
  const svg = drawSvg();
  fadeOut();
  return Object.assign(svg.node(), {
    updateCellValue,
    updateCellClass,
    fadeIn,
    fadeOut,
    offer,
    poll,
  });
};
