import * as React from 'react';
import { memo} from 'react'
import { useNavigate } from 'react-router-dom';
import { styled } from '@mui/material/styles';
import Stack from '@mui/material/Stack';
import IconButton from '@mui/material/IconButton';
import MoreHorizIcon from '@mui/icons-material/MoreHoriz';
import Grid from '@mui/material/Grid2';
import Card from '@mui/material/Card';
import CardMedia from '@mui/material/CardMedia';
import Typography from '@mui/material/Typography';
import { useTheme } from '@mui/material/styles';
console.log("######### Dashboard.js ######### ");

function shuffleArray(array) {
    for (var i = array.length - 1; i >= 0; i--) {
        var j = Math.floor(Math.random() * (i + 1));
        var temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
    return array;
}
function Dashboard() {
    const theme = useTheme();

    console.log("dashboard "+window.location.href)
    const navigate = useNavigate(); // Get the navigate function


    const Skeleton = styled('div')(({ theme, height }) => ({
      backgroundColor: theme.palette.action.hover,
      borderRadius: theme.shape.borderRadius,
      height,
      content: '" "',
    }));
  const algorithms = shuffleArray([
        { title: 'Binary Search', segment:"searching", link: '/algorithms/searching/undefined', img: './'+theme.palette.mode+'/searching.png'},
        { title: 'Arrays', segment:"arrays", link: '/algorithms/arrays/undefined', img: './'+theme.palette.mode+'/arrays.png'},
        { title: 'Sorting', segment:"sorting", link: '/algorithms/sorting/undefined', img: './'+theme.palette.mode+'/sorting.png'},
        { title: 'Lists', segment:"lists", link: '/algorithms/lists/undefined', img: './'+theme.palette.mode+'/lists.png'},
        { title: 'Grids', segment:"grids", link: '/algorithms/grids/undefined', img: './'+theme.palette.mode+'/grids.png'},
        { title: 'Stacks', segment:"stacks", link: '/algorithms/stacks/undefined', img: './'+theme.palette.mode+'/stacks.png'},
        { title: 'Queues', segment:"queues", link: '/algorithms/queues/undefined', img: './'+theme.palette.mode+'/queues.png'},
        { title: 'binary_tree', segment:"trees", link: '/algorithms/trees/binary_tree', img: './'+theme.palette.mode+'/trees.png'},
        { title: 'nary_tree', segment:"trees", link: '/algorithms/trees/undefined', img: './'+theme.palette.mode+'/trees.png'},
        { title: 'undirected first', segment:"graphs", link: '/algorithms/graphs/my_first', img: './'+theme.palette.mode+'/graphs.png',},
        { title: 'directed first', segment:"graphs", link: '/algorithms/graphs/gpt_first', img: './'+theme.palette.mode+'/digraphs.png',},
        { title: 'DAG first', segment:"graphs", link: '/algorithms/graphs/gpt_first', img: './'+theme.palette.mode+'/digraphs.png',},
        { title: 'UF first', segment:"graphs", link: '/algorithms/graphs/gpt_first', img: './'+theme.palette.mode+'/digraphs.png',},
        { title: 'DP', segment:"dp", link: '/algorithms/dp/undefined', img: 'https://mui.com/static/images/cards/contemplative-reptile.jpg' },
      ]);


    const books = shuffleArray([
        { name: 'LeetCode Notes', link: '/books/leetcode', img: 'https://mui.com/static/images/cards/contemplative-reptile.jpg'},
        { name: 'Design Patterns', link: '/books/designpattern', img: 'https://mui.com/static/images/cards/contemplative-reptile.jpg', more: "/algorithms/lists"},
        { name: '天龙八部', link: '/algorithms/trees', img: 'https://mui.com/static/images/cards/contemplative-reptile.jpg' },
        { name: '笑傲江湖', link: '/algorithms/trees', img: 'https://mui.com/static/images/cards/contemplative-reptile.jpg' },
        { name: '射雕英雄传', link: '/algorithms/graphs/gpt_second', more: "/algorithms/graphs", img: 'https://mui.com/static/images/cards/contemplative-reptile.jpg'},
        { name: 'Search', link: '/algorithms/', img: 'https://mui.com/static/images/cards/contemplative-reptile.jpg'},
        { name: 'DP', link: '/algorithms/', img: 'https://mui.com/static/images/cards/contemplative-reptile.jpg' },
        { name: 'Sliding Window', link: '/algorithms/', img: 'https://mui.com/static/images/cards/contemplative-reptile.jpg' },
      ]);
    return (
    <Grid container spacing={1}>
        <Grid size={5} />
        <Grid size={12}>
          <Skeleton height={14} />
        </Grid>
        <Grid size={12}>
          <Skeleton height={14} />
        </Grid>
        <Grid size={4}>
          <Skeleton height={100} />
        </Grid>
        <Grid size={8}>
          <Skeleton height={100} />
        </Grid>

        <Grid size={12}>

        </Grid>
        <Grid size={12}>
          <Skeleton height={14} />Algorithms<Skeleton height={14} />
        </Grid>
        {algorithms.map((algorithm, idx) => (
            <Grid
                size={{
                  xs: 12,
                  sm: 6,
                  md: 4,
                  lg: 3,
                }}
                key={idx}
            >
                <Card sx={{  cursor: 'pointer' }}>
                  <CardMedia
                    component="img"
                    alt="green iguana"
                    height="200"
                    image={algorithm.img}
                    onClick={()=> {navigate(algorithm.link)}}
                  />
                        <Stack spacing={0} p={2} direction="row" sx={{
                                               justifyContent: "space-between",
                                               alignItems: "center",
                                               paddingRight: "0px"
                                             }}>
                            <Typography variant="body2" sx={{ color: 'text.secondary' }}
                                onClick={()=> {navigate(algorithm.link)}}
                            >
                              {algorithm.title}
                            </Typography>
                            <IconButton color="primary" aria-label="minimize"
                                onClick={()=> {navigate(algorithm.more)}}
                                >
                                <MoreHorizIcon size="small" fontSize="small"/>
                            </IconButton>
                        </Stack>
                </Card>
            </Grid>
        ))}



        <Grid size={12}>
          <Skeleton height={14} />Graphite<Skeleton height={14} />
        </Grid>
        {/*graphs*/}
        <Grid size={{
                                xs: 12,
                                sm: 6,
                              }}>
          <Card sx={{  cursor: 'pointer' }}
              onClick={()=> {
                  navigate('/graphite/abc')
              }}
          >
              <CardMedia
                component="img"
                alt="green iguana"
                height="150"
                image={"./"+theme.palette.mode+"/graphite.png"}
              />
            </Card>
        </Grid>
        <Grid size={{
                                xs: 12,
                                sm: 6,
                              }}>
          <Card sx={{  cursor: 'pointer' }}
              onClick={()=> {
                  navigate('/graphite/abc')
              }}
          >
              <CardMedia
                component="img"
                alt="green iguana"
                height="150"
                image={"./"+theme.palette.mode+"/graphite.png"}
              />
            </Card>
        </Grid>
        <Grid size={12}>
          <Skeleton height={14} />Books<Skeleton height={14} />
        </Grid>

        {/*books*/}

        {books.map((algorithm, idx) => (
            <Grid
                key={idx}
                size={{
                  xs: 12,
                  sm: 6,
                  md: 4,
                  lg: 3,
                }}
            >
                <Card sx={{  cursor: 'pointer' }}>
                  <CardMedia
                    component="img"
                    alt="green iguana"
                    height="140"
                    image={algorithm.img}
                    onClick={()=> {navigate(algorithm.link)}}
                  />
                        <Stack spacing={0} p={2} direction="row" sx={{
                                               justifyContent: "space-between",
                                               alignItems: "center",
                                               paddingRight: "8px"
                                             }}>
                            <Typography variant="body2" sx={{ color: 'text.secondary' }}
                                onClick={()=> {navigate(algorithm.link)}}
                            >
                              {algorithm.name}
                            </Typography>
                            <IconButton color="primary" aria-label="minimize"
                                onClick={()=> {navigate(algorithm.more)}}
                                >
                                <MoreHorizIcon size="small" fontSize="small"/>
                            </IconButton>
                        </Stack>
                </Card>
            </Grid>
        ))}

        {/*other*/}
        <Grid size={12}>
          <Skeleton height={150} />
        </Grid>
        <Grid size={12}>
          <Skeleton height={14} />
        </Grid>

        <Grid size={3}>
          <Skeleton height={100} />
        </Grid>
        <Grid size={3}>
          <Skeleton height={100} />
        </Grid>
        <Grid size={3}>
          <Skeleton height={100} />
        </Grid>
        <Grid size={3}>
          <Skeleton height={100} />
        </Grid>
      </Grid>
    )
}
export default memo(Dashboard)