const renderGraph = (data, idx, loop) => {
        var that = this;
        const graphCanvas = document.querySelector(".graphCanvas");
        if(!graphCanvas) return;
            d3.select(".graphCanvas").graphviz()
                .transition(function() {
                  return d3.transition()
                      .duration(1000);
                })
            .fit(true)
            .zoom(true)//disable d3 graphviz zoom, to make svgPanZoom work
            .dot(data[idx])
            .render()
            .on("end", function(){
                if(!loop) return;
                if(idx<data.length-1) {
                    renderGraph(data, idx+1, loop);
                } else {
                    idx = 0;
                }
             });
        }


  function traverseGraphDFS() {
    renderGraph(dotSrcs, 0, true);
  }
    function unionFind() {
      renderGraph(unionFindSrc, 0, true);
    }
class D3List extends Component {
  constructor() {
    console.log("algorithms/lists "+window.location.href)
    super();

  }

  componentDidMount() {
    renderGraph(dotSrcs, 0);
  };
    record = (algorithmId) => {
        this.pause = false;
        const allAlgorithms = this.getSupportedAlgorithms();
        for(let i=0;i < allAlgorithms.length; i++) {
            if(allAlgorithms[i].id===algorithmId) {
                try {
                    return allAlgorithms[i].fn();
                } catch (err) {
                    console.log(err)
                }
            }
        }
    }
    getSupportedAlgorithms = () => {
        return [
            {
                id: "ll",
                name: "Linked List",
                icon: <Cloud fontSize="small" />,
                fn: ()=>{
                    return traverseGraphDFS()
                },
                selected: 0,
                disabled: false
            },
            {
                id: "uf",
                name: "Union Find",
                icon: <Cloud fontSize="small" />,
                fn: ()=>{
                    return unionFind()
                },
                selected: 0,
                disabled: false
            },
        ];
    }
    render() {
        return (
            <>
            <div className={"graphCanvas FlexScrollPaneInFlex"} ></div>
            </>

        );
    }
}

export default memo(D3List);