function DemoPageContent({ pathname }) {
//    const navigate = useNavigate();
//    navigate(pathname)

    if(pathname==="/" || pathname.endsWith("/dashboard")) return <Dashboard />
    if(pathname.endsWith("/algorithms")) return <Algorithms />
    if(pathname.endsWith("/algorithms/lists")) {
        window.history.replaceState(null, "New Page Title", "/pathname/goes/here")

        return <Algorithm alg="lists" />
    }
    if(pathname.endsWith("/algorithms/trees")) return <Algorithm alg="trees" />
    if(pathname.endsWith("/algorithms/graphs")) return <Algorithm alg="graphs" />
    if(pathname.endsWith("/graphite")) return <Graphite />
    if(pathname.endsWith("/about")) return <About />
    if(pathname.endsWith("/history")) return <History />
    if(pathname.endsWith("/contacts")) return <contacts />
    if(pathname.endsWith("/photos")) return <Photos />
    if(pathname.endsWith("/maps")) return <Maps />
    if(pathname.endsWith("/books")) return <Books />
    if(pathname.endsWith("/books/leetcode")) return <Book url="https://taobook.github.io/leetcode" />
    if(pathname.endsWith("/books/designpattern")) return <Book url="https://taobook.github.io/leetcode"/>
    console.log("show other "+ pathname)
  return (
        <>not found {pathname}</>
    );
}
