import * as React from 'react';
import Card from '@mui/material/Card';
import CardActions from '@mui/material/CardActions';
import CardContent from '@mui/material/CardContent';
import CardMedia from '@mui/material/CardMedia';
import Button from '@mui/material/Button';
import Typography from '@mui/material/Typography';
import Grid from '@mui/material/Grid2';
import Box from '@mui/material/Box';
import { useNavigate, useParams} from 'react-router-dom';

export default function Photos() {
  const {alb} = useParams();
  const algorithms = [
    { title: 'Min Operations', segment:"combos", link: '/algorithms/combos/1598', img: './dark/combos.png'},
    { title: 'Binary Search', segment:"searching", link: '/algorithms/searching/undefined', img: './dark/searching.png'},
    { title: 'Arrays', segment:"arrays", link: '/algorithms/arrays/undefined', img: './dark/arrays.png'},
    { title: 'Sorting', segment:"sorting", link: '/algorithms/sorting/undefined', img: './dark/sorting.png'},
    { title: 'Lists', segment:"lists", link: '/algorithms/lists/undefined', img: './dark/lists.png'},
    { title: 'Grids', segment:"grids", link: '/algorithms/grids/undefined', img: './dark/grids.png'},
    { title: 'Stacks', segment:"stacks", link: '/algorithms/stacks/undefined', img: './dark/stacks.png'},
    { title: 'Queues', segment:"queues", link: '/algorithms/queues/undefined', img: './dark/queues.png'},
    { title: 'binary_tree', segment:"trees", link: '/algorithms/trees/binary_tree', img: './dark/trees.png'},
    { title: 'nary_tree', segment:"trees", link: '/algorithms/trees/nary_tree', img: './dark/nary_trees.png'},
    { title: 'undirected first', segment:"2024", link: '/algorithms/graphs/my_first', img: './dark/graphs.png',},
    { title: 'directed first', segment:"2024", link: '/algorithms/graphs/gpt_first', img: './dark/digraphs.png',},
    { title: 'DAG first', segment:"2024", link: '/algorithms/graphs/gpt_first', img: './dark/digraphs.png',},
    { title: 'UF first', segment:"2024", link: '/algorithms/graphs/gpt_first', img: './dark/digraphs.png',},
    { title: 'Sample', segment:"2024", link: '/algorithms/graphs/sample', img: './dark/digraphs.png',},
    { title: 'DP', segment:"dp", link: '/algorithms/dp/undefined', img: 'https://mui.com/static/images/cards/contemplative-reptile.jpg' },
  ];

  return (
<Box sx={{ flexGrow: 1, p: 0 }} style={{margin:'0px'}}>
      <Grid
        container
        spacing={1}
        sx={{
          '--Grid-borderWidth': '1px',
          borderTop: 'var(--Grid-borderWidth) solid',
          borderLeft: 'var(--Grid-borderWidth) solid',
          borderColor: 'divider',
          '& > div': {
            borderRight: 'var(--Grid-borderWidth) solid',
            borderBottom: 'var(--Grid-borderWidth) solid',
            borderColor: 'divider',
          },
        }}
      >
        {
        algorithms
        .filter((photo) => !alb || photo.segment===alb)
        .map((photo, index) => (
          <Grid
            key={index}
            minHeight={160}
            size={{
              xs: 12,
              sm: 6,
              md: 4,
              lg: 3,
            }}
          >

                <Card sx={{ }}>
                      <CardMedia
                        component="img"
                        alt="green iguana"
                        height="140"
                        image="https://mui.com/static/images/cards/contemplative-reptile.jpg"
                      />
                      <CardContent>
                        <Typography gutterBottom variant="h5" component="div">
                          {photo.title}
                        </Typography>
                        <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                          {photo.segment}
                        </Typography>
                      </CardContent>
                      <CardActions>
                        <Button size="small">Share</Button>
                        <Button size="small">Learn More</Button>
                      </CardActions>
                    </Card>

          </Grid>
        ))}
      </Grid>
    </Box>

  );
}